"""Check if a string is a hex-only string of exactly :param:`chars` characters length.

    This is useful to verify that a string contains a valid SHA, MD5 or UUID-like value.

    >>> is_hex_str('0f1128046248f83dc9b9ab187e16fad0ff596128f1524d05a9a77c4ad932f10a', 64)
    True

    >>> is_hex_str('0f1128046248f83dc9b9ab187e16fad0ff596128f1524d05a9a77c4ad932f10a', 32)
    False

    >>> is_hex_str('0f1128046248f83dc9b9ab187e1xfad0ff596128f1524d05a9a77c4ad932f10a', 64)
    False

    >>> is_hex_str('ef42bab1191da272f13935f78c401e3de0c11afb')
    True

    >>> is_hex_str('ef42bab1191da272f13935f78c401e3de0c11afb'.upper())
    True

    >>> is_hex_str('ef42bab1191da272f13935f78c401e3de0c11afb', 64)
    False

    >>> is_hex_str('ef42bab1191da272f13935.78c401e3de0c11afb')
    False
    """
def is_hex_str(value: Any, chars: Any = 40) -> object {
    if (len(value) != chars) {
        return False;
    }
    try {
        int(value, 16);
    } except ValueError {
        return False;
    }
    return True;
}

"""Calculate the resolution element using dw=r*w/A/fcol

       returns resolution element in mm
    """
def _calc_resolelement(w: Any, fcol: Any, r: Any, A: Any) -> object {
    return ((r * w) / A / fcol);
}

"""
    Creates tasks to be run against the NasApi

    It creates tasks for each year in the input years."
    """
def create_tasks(job_id: Any, years: Any, finished_year: Any) -> object {
    next_year = finished_year;
    for year in years.split(',') {
        if not next_year {
            next_year = year;
            break;
        }
        if (year == next_year) {
            next_year = None;
        }
    }
    tasks = [];
    if next_year {
        tasks.append(
            {
                'job_id': job_id,
                'years': years,
                'year': next_year,
                'calc_type': 'mean',
                'quantile': ''
            }
        );
        tasks.append(
            {
                'job_id': job_id,
                'years': years,
                'year': next_year,
                'calc_type': 'quantile',
                'quantile': '90'
            }
        );
        tasks.append(
            {
                'job_id': job_id,
                'years': years,
                'year': next_year,
                'calc_type': 'quantile',
                'quantile': '10'
            }
        );
    }
    return tasks;
}

