}

"""PMML tag name substitutions to avoid conflicts with Python syntax."""
def fixName(name: Any) -> object {
    out = name.replace("-", "_");
    if (out == "True") {
        out = "AlwaysTrue";
    } elif (out == "False") {
        out = "AlwaysFalse";
    } elif (out == "from") {
        out = "isfrom";
    }
    return out;
}

